let fichaAntiga = {};
try {
  // @ts-ignore
  fichaAntiga = $('Traz dados salvos do usuário').item.json.dados || {};
} catch(e) {
  fichaAntiga = {};
}

let fichaNova = {};
try {
  // Adicionado o $json.text, pois alguns nós do n8n retornam o output aí
  let outputIA = $json.output || $json.text || $json.message?.content; 

  if (typeof outputIA === 'object' && outputIA !== null) {
      fichaNova = outputIA;
  } else if (typeof outputIA === 'string') {
      // A MÁGICA 1: Limpa os "```json" malditos antes de tentar converter
      let textoLimpo = outputIA.replace(/```json/g, '').replace(/```/g, '').trim();
      fichaNova = JSON.parse(textoLimpo);
  }
} catch(e) {
  const mensagemErro = e instanceof Error ? e.message : String(e);
  console.log("Erro ao converter JSON da IA:", mensagemErro);
  fichaNova = {};
}

// A MÁGICA 2: Remove chaves vazias ou nulas que a IA mandou
// Isso impede de sobrescrever dados bons antigos com 'null'
let fichaNovaLimpa = {};
for (const [chave, valor] of Object.entries(fichaNova)) {
    if (valor !== null && valor !== "" && valor !== "null") {
        fichaNovaLimpa[chave] = valor;
    }
}

// Junta as duas, priorizando a fichaNovaLimpa (que agora só tem dados reais)
const fichaFundida = { ...fichaAntiga, ...fichaNovaLimpa };

// Verifica se a IA *realmente* mandou alguma informação útil
const temDadoNovo = Object.keys(fichaNovaLimpa).length > 0;

return { 
  json: { 
    dados_finais: fichaFundida,
    salvar_no_banco: temDadoNovo,
    _debug_output_original: $json.output || $json.text // Adicionado para você ver o que a IA respondeu de fato
  } 
};

